<style>
.dl-inner{min-height:45vh}.dl-inner-hero{padding:48px 0;background:var(--dl-cream);color:var(--dl-forest)}.dl-inner-hero h1{font-size:clamp(28px,4vw,44px);line-height:1.25;margin:16px 0;overflow-wrap:anywhere}.dl-inner-hero a{color:var(--dl-olive)}.dl-inner-hero p{line-height:1.7;max-width:760px}.dl-content{padding-top:48px;padding-bottom:64px}.dl-prose{line-height:1.85;overflow-wrap:anywhere}.dl-prose img,.dl-prose video,.dl-prose iframe{max-width:100%}.dl-prose img{height:auto}.dl-prose figure{max-width:100%;margin-inline:0;overflow-x:auto}.dl-prose table{max-width:100%}.dl-prose a:not(.dl-primary){color:var(--dl-olive)}.dl-content-image{display:block;max-height:520px;object-fit:cover;border-radius:16px;margin:0 auto 32px}.dl-listing{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.dl-listing article{border:1px solid var(--dl-line);border-radius:14px;overflow:hidden}.dl-listing article>div{padding:24px}.dl-listing img{display:block;width:100%;aspect-ratio:16/10;object-fit:cover}.dl-listing h2{font-size:22px;line-height:1.4;margin:0 0 16px;overflow-wrap:anywhere}.dl-listing h2 a{color:var(--dl-forest);text-decoration:none}.dl-listing p{line-height:1.7}.dl-catalog-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.dl-catalog-grid .dl-product-card{border:1px solid var(--dl-line);border-radius:14px;min-width:0}.dl-product-detail{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:48px}.dl-product-detail h1{font-size:clamp(26px,3vw,38px);line-height:1.3}.dl-product-image img{width:100%;max-height:580px;object-fit:contain}.dl-price{font-size:28px;font-weight:800;color:var(--dl-olive)}.dl-purchase{display:flex;align-items:end;flex-wrap:wrap;gap:16px;margin:24px 0}.dl-purchase label{display:grid;gap:8px}.dl-purchase input{width:90px;padding:12px;border:1px solid var(--dl-line);border-radius:6px;font:inherit}.dl-inner .dl-primary{border:0;font:inherit;font-weight:700;cursor:pointer}.dl-pagination{display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:24px;margin-top:36px}.dl-footer-grid{grid-template-columns:minmax(0,1.3fr) minmax(0,1fr) minmax(0,1fr) minmax(0,1.4fr)}.dl-footer-grid>div{min-width:0;overflow-wrap:anywhere}.dl-footer-grid input{min-width:0}.dl-footer-grid button{flex-shrink:0}
@media(max-width:980px){.dl-listing,.dl-catalog-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.dl-footer-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:640px){.dl-inner-hero{padding:28px 0}.dl-content{padding-top:30px;padding-bottom:40px}.dl-listing,.dl-catalog-grid,.dl-product-detail,.dl-footer-grid{grid-template-columns:minmax(0,1fr)}.dl-product-detail{gap:24px}}
</style>
